\label{rem:towerp2}
For $n=2$ no carry occurs: $s=[s_0]+V(s_1)$ and $V(s_1)=V(\wp v)=\wp V(v)$ over $K(v)$, $v^p-v=s_1$, so $s\equiv[s_0]$ over $K(v)$. For $(p,n)=(2,3)$, with $v_i^2+v_i=s_i$, the formulas \eqref{eq:add2}--\eqref{eq:wp2} give $\wp(0,v_1,0)=(0,s_1,v_1^3+v_1^2)$ and hence
\begin{gather*}
s\equiv(s_0,0,\ c)\ \text{over }K(v_1),\ \ c=s_2+s_1^2+s_1v_1;\qquad s\equiv(s_0,0,\ s_1^2+s_1v_1)\ \text{over }K(v_1,v_2);\\
s\equiv(s_0,0,0)\ \text{over }K(v_1,v'),
\end{gather*}
where $v'^2+v'=c$ (these are the specialisations $x=(0,v_1,0)$, $(0,v_1,v_2)$, $(0,v_1,v')$ of the general translate of Appendix~\ref{app:witt}). The middle class is not $(s_0,0,0)$: $s_1^2+s_1v_1=v_1^4+v_1^3\equiv v_1^3+v_1\bmod\wp K(v_1,v_2)$, and $v_1^3+v_1\notin\wp\,k(s_0,v_2)(v_1)$, since it has a pole of odd order $3$ at $v_1=\infty$ while an element $w^2+w$ has a pole of even order or none there. So the quartic extension $K(v_1,v_2)$ does not kill the two upper layers of the class, although both $s_1$ and $s_2$ become $\wp$-exact over it; in fact $\operatorname{ed}_k(\tau_{\mathrm{gen}}\otimes K(v_1,v_2))=2$ (Theorem~\ref{thm:fam}(c)), so $K(v_1,v_2)$ is not a witness for $\operatorname{ed}^{[4]}_k(\tau_{\mathrm{gen}})\le1$, while the tower $K(v_1,v')$ of Lemma~\ref{lem:tower} is.

\label{lem:twistL}
Let $C$ be a quasi-projective $G$-variety over $k$ and $X:={}^{\tau_{\mathrm{gen}}}\!C$. There is an $L$-isomorphism $\psi\colon X\otimes_KL\xrightarrow{\sim}C\otimes_kL$ such that
\begin{enumerate}[label=\textup{(\alph*)}]
\item for every $h\in G$, $\psi$ intertwines the automorphism $\operatorname{id}_X\times\operatorname{Spec}(h)$ of $X\otimes_KL$ with $\phi_h:=h_C\times\operatorname{Spec}(h)$ ($\psi$ is $L$-linear, while $\phi_h$ is semilinear over $\operatorname{Spec}(h)$);
\item for every field $F'\supseteq K$ and $P\in X(F')$, the composite $\mathrm{pr}_1\circ\psi\circ(P\times_K\operatorname{id}_{\operatorname{Spec} L})\colon\operatorname{Spec}(F'\otimes_KL)\to C$ is the $G$-equivariant morphism attached to $P$ by Fact~[A,\,\ref{A-fact:rs}](a).
\end{enumerate}

\label{lem:lnformula}
Recall $\overline{U}_0=\mathbb{P}^1_t$, so $g(\overline{U}_0)=0$.
\begin{enumerate}[label=\textup{(\alph*)}]
\item The upper ramification breaks of $\overline{U}_n\to\mathbb{P}^1_t$ at $\infty$ are $1,p,\dots,p^{n-1}$; consequently the lower breaks are the numbers $1+(p-1)\sum_{i=1}^{j-1}p^{2i-1}$, $1\le j\le n$, and
\begin{equation}\label{eq:ln}
\begin{gathered}
l_n(p)=1+(p-1)\sum_{j=1}^{n-1}p^{2j-1}=\frac{p^{2n-1}+1}{p+1}:\\
l_2(2)=3,\quad l_2(p)=p^2-p+1,\quad l_3(2)=11,\quad l_4(2)=43,\quad l_3(3)=61 .
\end{gathered}
\end{equation}
In particular $l_{m+1}(p)=p^2\,l_m(p)-p+1$ for $m\ge1$.
\item $2g(\overline{U}_m)-2=p\,(2g(\overline{U}_{m-1})-2)+(p-1)(l_m(p)+1)$ for $m\ge1$.
\item $l_m(p)=p\,(2g(\overline{U}_{m-1})-1)+p^m+1$ for $m\ge1$.
\end{enumerate}

\label{lem:fibration}
Let $\pi\colon V\to B$ be a dominant morphism of integral $k$-varieties whose generic fibre $V_\eta$ is geometrically integral, and let $\phi\colon V\dashrightarrow C$ be a dominant rational map to a smooth projective curve. Then either
\begin{enumerate}[label=\textup{(\roman*)}]
\item there is a dense open subset $B^\circ\subseteq B$ such that for every closed point $b\in B^\circ$ the fibre $V_b$ is integral, $\phi$ restricts to a rational map $V_b\dashrightarrow C$, and this map is dominant; or
\item $k(C)\subseteq k(B)$, so that $C$ is dominated by $B$.
\end{enumerate}

\label{thm:fam}
$\operatorname{ed}_k(\tau_{\mathrm{gen}}\otimes K')=2$ for each of the following fields $K'$:
\begin{enumerate}[label=\textup{(\alph*)}]
\item $K'=K(v_f)$ with $f\in s_2+K_2+\wp K$ \textup{(}this contains $K(v_2)$\textup{)};
\item $K'=K(v_1)$ and $K'=K(z_0)=K(v_0)$;
\item the quartic tower $K'=K(v_1,v_2)$.
\end{enumerate}
In particular the quartic tower $K(v_1,v_2)$ is not a witness for $\operatorname{ed}^{[4]}_k(\tau_{\mathrm{gen}})=1$.

\label{thm:status}
\[
\operatorname{ed}^{[1]}\in\{2,3\},\quad\operatorname{ed}^{[2]}=\operatorname{ed}^{[3]}=2,\quad
\operatorname{ed}^{[4]}=\dots=\operatorname{ed}^{[7]}=1,\quad\operatorname{ed}^{[8]}=0;
\]
$d_2\in\{1,2\}$, $d_1=4$, $d_0=8$; for the prime-to-$2$ profile, $\operatorname{ed}^{[1]}{}'=\operatorname{ed}^{[2]}{}'=\operatorname{ed}^{[1]}$, $\operatorname{ed}^{[3]}{}'=\operatorname{ed}^{[4]}{}'=2$, $d_2^{(p')}\in\{1,3\}$, $d_1^{(p')}=11$, and $d_0^{(p')}=\infty$. Every faithful $\mathbb{Z}/8$-curve $C$ has $D(C)\cap\{1,2,3\}=\emptyset$; $D(U_3)\supseteq\langle4,6,11\rangle\smallsetminus\{0\}$ and $\delta_\mathrm{free}(U_3)=4$, $5,7,9\notin D(C)$ for every faithful $\mathbb{Z}/8$-curve $C$, while it is not known whether $13\in D(U_3)$. The quartic tower $K(v_1,v_2)$ is not a witness for $\operatorname{ed}^{[4]}=1$ (Theorem~\ref{thm:fam}(c)), while $K(v_1,v')$ is (Lemma~\ref{lem:tower}).

\label{prop:layers}
For $n\ge2$ and $d\ge1$:
\begin{enumerate}[label=\textup{(\alph*)}]
\item $f(n-1,d)\le f(n,d)\le f(n-1,d)+1$;
\item $f(n,pd)\le f(n-1,d)$.
\end{enumerate}
Consequently, with $\delta_m(d):=f(m,d)-f(m-1,d)$ \textup{(}$f(0,d):=0$; $\delta_1(d)=f(1,d)\in\{0,1\}$ since $\operatorname{ed}_k(\mathbb{Z}/p)=1$, and $\delta_m(d)\in\{0,1\}$ for $m\ge2$ by \textup{(a)}\textup{)}, we have $f(n,p^j)=\sum_{m=j+1}^n\delta_m(p^j)$, and $P(n,j)$, the statement $f(n,p^j)=n-j$, holds iff $\delta_m(p^j)=1$ for all $j<m\le n$: every Witt layer is strict.

\label{cor:Pn1}
\begin{enumerate}[label=\textup{(\alph*)}]
\item $P(n,1)$ implies $\mathrm{Led}(n-1)$ and $P(n-1,1)$. In particular $P(n,1)$ for all $n$ implies Ledet's conjecture for all $n$, and the subgroup formula at $j=1$ for $\mathbb{Z}/p^4$ contains $\operatorname{ed}_k(\mathbb{Z}/p^3)=3$.
\item $D'(2)$ is trivial and $D'(3)$ holds for every $p$ \textup{(}Theorem~\ref{thm:N1}\textup{)}; hence $P(3,1)$ holds for every $p$. For $n\ge4$, $D'(n)$ is open.
\end{enumerate}

\label{prop:DX}
\begin{enumerate}[label=\textup{(\alph*)}]
\item Let $X$ be an irreducible quasi-projective surface with a faithful $G$-action. The following are equivalent: \textup{(i)} $1\in D(X)$; \textup{(ii)} $X$ is $\tau_{\mathrm{gen}}$-versal; \textup{(iii)} there is a $G$-compression $W_3\dashrightarrow X$. Moreover, $\delta_\mathrm{free}(X)\ge2$ for every smooth projective surface $X$ with a faithful $G$-action iff $\operatorname{ed}_k(\mathbb{Z}/p^3)=3$.
\item Let $X$ be a smooth projective surface with a faithful $G$-action and a $G$-fixed $k$-point. Then ${}^{\tau_{\mathrm{gen}}}\!X(K)\ne\emptyset$ (the constant map to the fixed point, Fact~[A,\,\ref{A-fact:rs}](a)); in particular the index and elementary obstruction of ${}^{\tau_{\mathrm{gen}}}\!X$ are trivial.
\item $d_2(\tau_{\mathrm{gen}})\le p$, and $d_2(\tau_{\mathrm{gen}})=\min_Z\delta_\mathrm{free}(Z)$ over quasi-projective generically free primitive $G$-varieties $Z$ of dimension $\le2$; the minimum over smooth projective surfaces with faithful $G$-action equals $1$ iff $\operatorname{ed}_k(\mathbb{Z}/p^3)\le2$.
\end{enumerate}
